out = [[7]*24 for _ in range(20)]
# horizontal segments between outermost zeros
marks = {4:[15,16,18,19,20,21,22,23],5:[15,23],6:[15,23],7:[23],8:[15],9:[15,23],10:list(range(15,24))}
for r, cs in marks.items():
    for c in cs: out[r][c]=0
    if len(cs)>=2:
        for c in range(min(cs),max(cs)+1):
            if out[r][c] != 0: out[r][c]=2
# vertical segments
for c in range(24):
    rs=[r for r in range(20) if out[r][c]==0]
    if len(rs)>=2:
        for r in range(min(rs),max(rs)+1):
            if out[r][c] != 0: out[r][c]=2
print(out)
print([len(x) for x in out])
